import React, { useState } from 'react';
import { useSafeRace } from './safe-race';

const Test = ({ onLoadingMore, onClick }: { onLoadingMore: () => Promise<number>; onClick: () => void }) => {
  const safeFetch = useSafeRace(onLoadingMore, { enabled: false });

  return (
    <button
      onClick={() => {
        onClick();
        setTimeout(() => {
          void safeFetch();
        }, 1e3);
      }}
    >
      more
    </button>
  );
};

export default function Demo() {
  const [now, setNow] = useState(0);

  console.log('外部', now);
  const handleLoadingMore = () => {
    console.log('内部', now);
    return Promise.resolve(1);
  };

  return (
    <Test
      onLoadingMore={handleLoadingMore}
      onClick={() => {
        setNow(now + 1);
      }}
    />
  );
}
